SELECT 'gongkao', '十字交叉法', 'kp-conc-m-cross', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "十字交叉法"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心绝招：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "解决所有混合问题的终极杀器。利用浓度差直接反推出溶液的质量比。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、核心公式"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[左上: 高浓度 A%] --- C[中间: 混合浓度 C%]\nB[左下: 低浓度 B%] --- C\nC --- D[右上: |C% - B%| 对应高浓度液体的质量份额]\nC --- E[右下: |A% - C%| 对应低浓度液体的质量份额]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 20%的盐水与5%的盐水混合，得到15%的盐水。问两种盐水所需的质量比？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "左边写：20 和 5，中间写：15。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "左下到右上交叉减：15 - 5 = 10（写在右上）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "左上到右下交叉减：20 - 15 = 5（写在右下）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "得出比例：20%盐水 : 5%盐水 = 10 : 5 = 2 : 1。"}]}]}]}]}$$ AS jsonb), NULL, '十字交叉法的核心考点与实战推导。', category_node.id, CAST('["数量关系", "浓度问题", "十字交叉法"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_conc_m_cross", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
